if isnumeric(@id_hd) = 1 begin
  declare @tt_nt numeric(19,5)
  select @tt_nt = isnull(sum(tt_nt), 0) from ctqlq20 where id_tt = @id_hd
  select max(ngay_ct) as [#ngay_ct_hd],isnull(max(ma_ct), '') as [#ma_ct_hd], isnull(max(ma_nt), '') as [#ma_nt_hd], isnull(max(ty_gia), 0) as [#ty_gia_hd], isnull(max(t_tt), 0) as [#tien_hd_nt], @tt_nt as [#da_pb_nt], isnull(max(t_tt), 0) - @tt_nt as [#cl_nt]
  from ctqlq20 
  where id = @id_hd
end
else
	select null as [#ngay_ct_hd], '' as [#ma_nt_hd], 0 as [#tien_hd_nt], 0 as [#da_pb_nt]




